def is_prime(n):
    if n < 2:
        return False

    # Check for divisibility from 2 up to the square root of n
    # This optimization significantly reduces the number of checks needed
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False

        # Increment the divisor
        i += 1

    # If no divisors were found, the number is prime
    return True

