def capitalize_sentences(text):
    if not text:
        return ""

    result = []
    sentence_starters = ['.', '!', '?']
    capitalize_next = True

    for char in text:
        if capitalize_next and 'a' <= char <= 'z':
            result.append(char.upper())
            capitalize_next = False
        else:
            result.append(char)

        if char in sentence_starters:
            capitalize_next = True
        elif char.isalpha() and capitalize_next: # If we encounter a letter and are still in a "capitalize next" state
            capitalize_next = False            # it means the sentence has started, and we've already capitalized or it wasn't a letter.

    return "".join(result)

