    char_counts = {}
    first_occurrence = {}

    for i, char in enumerate(text):
        if char == ' ':
            continue

        char_lower = char.lower()

        if char_lower not in char_counts:
            char_counts[char_lower] = 0
            first_occurrence[char_lower] = i

        char_counts[char_lower] += 1

    if not char_counts:
        return None  # Handle empty string or string with only spaces

    max_count = -1
    result_char = None
    result_index = float('inf')

    for char, count in char_counts.items():
        if count > max_count:
            max_count = count
            result_char = char
            result_index = first_occurrence[char]
        elif count == max_count:
            if first_occurrence[char] < result_index:
                result_char = char
                result_index = first_occurrence[char]

