def run_length_encode(s):
    if not s:
        return ""

    encoded_string_parts = []
    current_char = s[0]
    current_count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            current_count += 1
        else:
            encoded_string_parts.append(current_char + str(current_count))
            current_char = s[i]
            current_count = 1

    encoded_string_parts.append(current_char + str(current_count))
    return "".join(encoded_string_parts)

