def binary_to_decimal(binary_string):
    decimal_value = 0
    power = 0
    for digit in reversed(binary_string):
        if digit == '1':
            decimal_value += 2 ** power
        elif digit != '0':
            raise ValueError("Invalid binary digit found.")
        power += 1
    return decimal_value

